+function describeStage(
+  stage: Extract<FileFlowState, { kind: 'cancelled' }>['cancelledAt'],
+): string {
+  switch (stage) {
+    case 'staging':
+      return 'copying the file';
+    case 'migrating':
+      return 'upgrading the copy';
+    case 'worker-open':
+      return 'opening the project file';
+    case 'hydrating':
+      return 'reading the contents';
+    case 'publishing':
+      return 'publishing';
+  }
+}
